#include <iostream>
using namespace std;

// Common bugs that cause crashes:
// 1. Using uninitialized pointers
// 2. Incorrect array bounds access
// 3. Memory allocation failures not checked
// 4. Incorrect row/column indexing

// Fixed and enhanced 2D array implementation
class Matrix {
private:
    int** data;
    int rows, cols;

public:
    // Constructor with proper memory allocation
    Matrix(int r, int c) : rows(r), cols(c) {
        // Allocate memory for rows
        data = new int*[rows];

        // Allocate memory for each row and initialize to zero
        for (int i = 0; i < rows; i++) {
            data[i] = new int[cols];
            for (int j = 0; j < cols; j++) {
                data[i][j] = 0;  // Initialize to avoid garbage values
            }
        }
    }

    // Destructor to prevent memory leaks
    ~Matrix() {
        for (int i = 0; i < rows; i++) {
            delete[] data[i];
        }
        delete[] data;
    }

    // Set value at position (i, j)
    void setValue(int i, int j, int value) {
        // Bounds checking to prevent crashes
        if (i >= 0 && i < rows && j >= 0 && j < cols) {
            data[i][j] = value;
        } else {
            cerr << "Error: Index out of bounds (" << i << ", " << j << ")" << endl;
        }
    }

    // Row-major traversal (left to right, top to bottom)
    void traverseRowMajor() {
        cout << "Row-Major Traversal:" << endl;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                cout << data[i][j] << " ";
            }
            cout << endl;
        }
    }

    // Column-major traversal (top to bottom, left to right)
    void traverseColumnMajor() {
        cout << "Column-Major Traversal:" << endl;
        for (int j = 0; j < cols; j++) {
            for (int i = 0; i < rows; i++) {
                cout << data[i][j] << " ";
            }
            cout << endl;
        }
    }

    // Get dimensions
    int getRows() const { return rows; }
    int getCols() const { return cols; }
};

int main() {
    // Create a 3x3 matrix
    Matrix matrix(3, 3);

    // Fill with values
    int count = 1;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            matrix.setValue(i, j, count++);
        }
    }

    // Test traversals
    matrix.traverseRowMajor();
    cout << endl;
    matrix.traverseColumnMajor();

    return 0;
}
```

